(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const D=window.TERRA;
 const periods=s=>s.chronicle?.periods||s.sections.map((x,i)=>({period:`阶段 ${i+1}`,title:x[0],body:x.slice(1).join('\n\n'),people:s.people.map(p=>p[0]),refs:[]}));
 const person=n=>window.ROSTER_RENDER?.byName(n);
 const canonical=p=>window.PERSON_BIOGRAPHIES.recordToPerson[p?.id]||p?.id;
 const phaseHref=(s,i)=>i==null?`#/story/${s.id}`:`#/story/${s.id}/part-${i}`;
 function peopleLinks(names,small=false){return [...new Set(names)].map(name=>{const p=person(name);return p?`<a class="event-person ${small?'compact':''}" href="#/character/${p.id}">${small?'':window.ART_UI?.thumb(p)||''}<span>${esc(name)} <b aria-hidden="true">↗</b></span></a>`:`<span class="event-person unlinked">${esc(name)}</span>`;}).join('');}
 function inline(text,names){const candidates=[];for(const n of names){const p=person(n);if(!p)continue;for(const name of [n,p.name,...(p.aliases||[])])if(name.length>1&&!/[／/、]/.test(name))candidates.push({name,p});}
 const aliases={'玛嘉烈':'临光','玛莉娅':'瑕光','恩雅':'初雪','恩希亚':'崖心','乔迪':'流明','祖玛玛':'森蚺','艾利奥特':'异客','洛伦茨':'谬因'};
 for(const [name,n] of Object.entries(aliases)){const p=person(n);if(p&&names.some(x=>canonical(person(x))===canonical(p)))candidates.push({name,p});}
 const unique=[...new Map(candidates.sort((a,b)=>b.name.length-a.name.length).map(x=>[x.name,x])).values()];if(!unique.length)return esc(text);
 const re=new RegExp(unique.map(x=>x.name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');let at=0,out='';for(const m of text.matchAll(re)){out+=esc(text.slice(at,m.index));const p=unique.find(x=>x.name===m[0]).p;out+=`<a class="inline-person" href="#/character/${p.id}">${esc(m[0])}</a>`;at=m.index+m[0].length;}return out+esc(text.slice(at));}
 function paragraphs(p,s,phase,names){const parts=p.body.split(/\n\s*\n/).filter(Boolean);return parts.map((t,i)=>`<p>${inline(t,[...names,...p.people])}</p>${(p.illustrations||[]).filter(u=>Math.max(1,Math.min(parts.length,u.afterParagraph||parts.length))===i+1).map(u=>window.STORY_IMAGE_UI?.figure(u,s.id,phase)||'').join('')}`).join('');}
 function renderPeriod(p,s,i,supplement=false){const names=s.people.map(x=>x[0]),n=window.ORIGIN_UI.periods(s).length+window.ORIGIN_UI.visible(s).findIndex(x=>x.i===i)+1;return `<section class="chapter-section region-period" id="part-${i}"><div class="period-label"><span>${supplement?'补记':String(n).padStart(2,'0')}</span>${esc(p.period)}</div><h2>${esc(p.title)}</h2>${paragraphs(p,s,i,names)}${p.people.length?`<div class="event-cast"><small>这一阶段的人物</small><div>${peopleLinks(p.people,true)}</div></div>`:''}${p.refs.length?`<div class="biography-evidence">材料：${p.refs.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)} ↗</a>`).join('；')}</div>`:''}</section>`;}
 function body(s){const O=window.ORIGIN_UI,cgCount=window.STORY_IMAGE_UI?.items(s).length||0,old=O.absorbed(s);return `<details class="region-mobile-toc"><summary>本篇目录 · ${O.periods(s).length} 段沿革 · ${O.visible(s).length} 段事件</summary>${O.periods(s).length?O.toc(s):periods(s).map((p,i)=>`<a href="#part-${i}" data-anchor="part-${i}">${esc(p.period)} · ${esc(p.title)}</a>`).join('')}${cgCount?`<a href="#story-cg-gallery" data-anchor="story-cg-gallery">本篇剧情图册 · ${cgCount} 张</a>`:''}</details>${O.render(s)}${old.length?`<details class="history-supplements" id="history-supplements"><summary>前史补记与人物旧事</summary><p>以下保留早期材料及相关人物经历，供回查阅读；不作为接续上一阶段的新事件。</p>${old.map(i=>renderPeriod(periods(s)[i],s,i,true)).join('')}</details>`:''}${O.modernHeading(s)}<div class="regional-timeline">${O.visible(s).map(({p,i})=>renderPeriod(p,s,i)).join('')}</div>${window.STORY_IMAGE_UI?.gallery(s)||''}`;}
 function cast(s,full){return `<section id="cast"><div class="section-head"><h2>相关人物纪事</h2></div><div class="regional-cast-grid">${s.people.map(x=>{const p=person(x[0]);return p?`<a class="regional-cast-card" href="#/character/${p.id}">${window.ART_UI?.thumb(p)||''}<div><h3>${esc(x[0])} ↗</h3><p>${full?esc(x[1]):'查看人物纪事'}</p></div></a>`:`<div class="regional-cast-card"><div><h3>${esc(x[0])}</h3><p>${full?esc(x[1]):'本篇人物'}</p></div></div>`;}).join('')}</div></section>`;}
 function associations(p){const id=canonical(p);return D.stories.flatMap(s=>{const rows=periods(s).map((x,i)=>({s,x,i})).filter(({x})=>x.people.some(n=>canonical(person(n))===id)||(p.name.length>1&&x.body.includes(p.name)));const historyRows=window.ORIGIN_UI.periods(s).filter(x=>x.people.some(n=>canonical(person(n))===id)).map(x=>({s,x,i:null,anchor:window.ORIGIN_UI.anchor(x)}));rows.unshift(...historyRows);return rows.length?rows:s.people.some(n=>canonical(person(n[0]))===id)?[{s,x:{period:'本篇相关人物',title:s.title,refs:[]},i:null}]:[];});}
 function backlinks(p,full){const a=associations(p);if(!a.length)return '';return `<section class="record-related regional-backlinks"><div class="eyebrow">EVENTS ACROSS THE LAND</div><h2>与地区事件对照阅读</h2><p class="index-boundary">从个人经历回到事件全貌；同一事件中的其他参与者也在地区篇中相连。</p>${[...new Set(a.map(z=>z.s.id))].map(id=>{const rows=a.filter(z=>z.s.id===id),s=rows[0].s;return `<div class="backlink-group"><a class="backlink-story" href="#/story/${s.id}">${esc(D.regions.find(r=>r.id===s.region).name)} · ${esc(s.title)} ↗</a>${full?`<div class="backlink-events">${rows.map(({x,i,anchor})=>`<a href="${anchor?'#/story/'+s.id+'/'+anchor:phaseHref(s,i)}"><span>${esc(x.period)}</span>${esc(x.title)} ↗</a>`).join('')}</div>`:''}</div>`;}).join('')}</section>`;}
 function periodLinks(p,period){const books=[...new Set((period.refs||[]).flatMap(x=>[...x.matchAll(/《([^》]+)》/g)].map(m=>m[1])))];const a=associations(p).filter(({x})=>x.refs.some(r=>books.some(b=>r.label.includes(`《${b}》`))));return a.length?`<div class="life-region-links"><small>地区事件</small>${a.slice(0,4).map(({s,x,i,anchor})=>`<a href="${anchor?'#/story/'+s.id+'/'+anchor:phaseHref(s,i)}">${esc(x.title)} ↗</a>`).join('')}</div>`:'';}
 function sourceNotes(s){const c=s.chronicle;if(!c)return '';return `<details class="source-details" id="story-sources"><summary>本篇出处与时序说明</summary><p>采用范围：${esc(s.scope)}</p><p>${esc(c.chronologyNote)}</p>${window.ORIGIN_UI.sources(s)}<ol>${c.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.label)} ↗</a></li>`).join('')}</ol><p class="source-caution">关卡链接指向社区公开镜像中的游戏原文；泰拉文库与 PRTS 是第三方阅读和转录入口。具体段落旁列出对应材料，年份未明的部分采用相对阶段，分支与梦境另行标示。<a href="#/sources">完整编写说明 ↗</a></p></details>`;}
 window.REGION_UI={periods,peopleLinks,inline,body,cast,associations,backlinks,periodLinks,sourceNotes};
})();
